/* Khayrukum service worker (OFF-02…11). Generated by tools/build.mjs: BUILD_HASH and PRECACHE are inlined,
   so every deploy that changes any file changes the bytes of sw.js (OFF-02a.1). */
const BUILD_HASH = '__BUILD_HASH__';
const PRECACHE = __PRECACHE__; // [{url, sha256, bytes}] relative to the scope
const AUDIO_MANIFESTS = __AUDIO_MANIFESTS__; // data/audio/*.json collection manifests (empty when audio is off)
const APP_CACHE = 'khayr-app-' + BUILD_HASH;
const AUDIO_CACHE = 'khayr-audio-v1';
const SCOPE = self.registration.scope;
const abs = u => new URL(u, SCOPE).href;

let bc = null; try { bc = new BroadcastChannel('khayrukum'); } catch (e) { bc = null; }
const announce = msg => { try { bc && bc.postMessage(msg); } catch (e) { /* ignore */ } self.clients.matchAll({ includeUncontrolled: true }).then(cs => cs.forEach(c => c.postMessage(msg))); };

async function hex(buf) { const d = await crypto.subtle.digest('SHA-256', buf); return [...new Uint8Array(d)].map(b => b.toString(16).padStart(2, '0')).join(''); }
const sleep = ms => new Promise(r => setTimeout(r, ms));

/** OFF-02a.3–4: fetch with cache:'reload' from a ?__v=<sha8> URL, verify the hash, store under the clean URL. */
async function fetchVerified(entry) {
  const u = new URL(entry.url, SCOPE); u.searchParams.set('__v', entry.sha256.slice(0, 8));
  const r = await fetch(u.href, { cache: 'reload', credentials: 'same-origin' });
  if (!r.ok) throw new Error('HTTP ' + r.status + ' ' + entry.url);
  const buf = await r.arrayBuffer();
  if ((await hex(buf)) !== entry.sha256) throw new Error('hash mismatch ' + entry.url);
  const headers = new Headers(r.headers); headers.delete('content-length');
  return new Response(buf, { status: 200, statusText: 'OK', headers });
}

self.addEventListener('install', event => {
  let existed = true; // a re-deploy of identical content reuses the cache name of the worker still in control
  event.waitUntil((async () => {
    existed = await caches.has(APP_CACHE);
    const cache = await caches.open(APP_CACHE);
    const failed = [];
    await Promise.all(PRECACHE.map(async e => {
      try { await cache.put(abs(e.url), await fetchVerified(e)); }
      catch (err) { failed.push(e); }
    }));
    if (failed.length) { // OFF-02a.5: one retry after 5 s, then fail the install (the old SW stays in control)
      await sleep(5000);
      for (const e of failed) await cache.put(abs(e.url), await fetchVerified(e));
    }
    announce({ type: 'precached', hash: BUILD_HASH });
  })().catch(async err => { if (!existed) await caches.delete(APP_CACHE); throw err; })); // never delete a cache that is in use (OFF-02a.5)
});

self.addEventListener('message', e => { if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting(); });

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('khayr-app-') && k !== APP_CACHE) await caches.delete(k); // OFF-11
    if (AUDIO_MANIFESTS.length) { // OFF-11: remove audio entries that are not in the current manifest
      const app = await caches.open(APP_CACHE); const keep = new Set();
      for (const m of AUDIO_MANIFESTS) {
        const r = await app.match(abs(m)); if (!r) continue;
        const man = await r.json();
        for (const it of man.items || []) keep.add(abs(it.src) + (it.sha256 ? '?v=' + it.sha256.slice(0, 8) : ''));
      }
      if (keep.size) { const ac = await caches.open(AUDIO_CACHE); for (const req of await ac.keys()) if (!keep.has(req.url)) await ac.delete(req); }
    }
    await self.clients.claim();
    announce({ type: 'activated', hash: BUILD_HASH });
  })());
});

/** OFF-07: answer a Range request from a cached full body. */
async function rangeResponse(cached, rangeHeader) {
  const buf = await cached.arrayBuffer(); const total = buf.byteLength;
  const m = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader.trim());
  let s, e;
  if (m && m[1] === '' && m[2] !== '') { const n = +m[2]; s = Math.max(0, total - n); e = total - 1; if (n === 0) s = total; }
  else if (m && m[1] !== '') { s = +m[1]; e = m[2] === '' ? total - 1 : Math.min(+m[2], total - 1); }
  if (!m || s === undefined || s >= total || s > e) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${total}` } });
  return new Response(buf.slice(s, e + 1), { status: 206, statusText: 'Partial Content', headers: {
    'Content-Range': `bytes ${s}-${e}/${total}`, 'Content-Length': String(e - s + 1), 'Accept-Ranges': 'bytes', 'Content-Type': 'audio/mpeg' } });
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // audio: served from khayr-audio-v1 (full or Range); never store a 206 (OFF-08)
  if (/\.mp3$/i.test(url.pathname)) {
    event.respondWith((async () => {
      const ac = await caches.open(AUDIO_CACHE);
      const hit = await ac.match(req.url);
      const range = req.headers.get('range');
      if (hit) return range ? rangeResponse(hit, range) : hit;
      return fetch(req); // uncached Range requests go to the network unchanged
    })());
    return;
  }

  // navigations: cache-first ignoring the query string, 404.html as the fallback (OFF-04)
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const app = await caches.open(APP_CACHE);
      let path = url.pathname; if (path.endsWith('/')) path += 'index.html';
      const hit = await app.match(new URL(path, url.origin).href) || await app.match(new URL(path + '/index.html', url.origin).href);
      if (hit) {
        // IA-05: «/plan» → «/plan/», as the server does; relative links depend on the trailing slash
        const dir = !path.endsWith('/index.html') && !/\.[a-z0-9]+$/i.test(path) && !(await app.match(new URL(path, url.origin).href));
        return dir ? Response.redirect(url.pathname + '/' + url.search, 301) : hit;
      }
      try { const r = await fetch(req); if (r.status === 404) return (await app.match(abs('404.html'))) || r; return r; }
      catch (e) { return (await app.match(abs('404.html'))) || Response.error(); }
    })());
    return;
  }

  // app assets and /data/**: cache-first from the app cache
  event.respondWith((async () => {
    const app = await caches.open(APP_CACHE);
    const clean = url.searchParams.has('__v') ? url.origin + url.pathname : req.url;
    const hit = await app.match(clean, { ignoreSearch: url.pathname.includes('/data/') });
    return hit || fetch(req);
  })());
});
